import{_ as n,o,c as a,a2 as l}from"./chunks/framework.BZO4qERu.js";const u=JSON.parse('{"title":"Jenkins安装与配置","description":"","frontmatter":{},"headers":[],"relativePath":"devops/jenkins-installation.md","filePath":"devops/jenkins-installation.md","lastUpdated":1781086744000}'),i={name:"devops/jenkins-installation.md"};function t(r,e,c,s,d,k){return o(),a("div",null,[...e[0]||(e[0]=[l(`<h1 id="jenkins安装与配置" tabindex="-1">Jenkins安装与配置 <a class="header-anchor" href="#jenkins安装与配置" aria-label="Permalink to &quot;Jenkins安装与配置&quot;">​</a></h1><h2 id="在centos上安装jenkins" tabindex="-1">在Centos上安装Jenkins <a class="header-anchor" href="#在centos上安装jenkins" aria-label="Permalink to &quot;在Centos上安装Jenkins&quot;">​</a></h2><p>下面介绍在Centos系统下安装jenkins的步骤</p><p>首先需要安装Java</p><pre><code>yum install java
</code></pre><p>然后把Jenkins库添加到yum中，Jenkins将从这里下载安装</p><pre><code>wget -O /etc/yum.repos.d/jenkins.repo http://pkg.jenkins-ci.org/redhat-stable/jenkins.repo
rpm --import https://jenkins-ci.org/redhat/jenkins-ci.org.key
yum install jenkins
</code></pre><p>安装过程完成后，用以下命令启动Jenkins</p><pre><code>systemctl start jenkins
</code></pre><p>用以下命令查看Jenkins启动状态</p><pre><code>systemctl status jenkins
</code></pre><p>如果想开机自动启动jenkins，可以执行以下命令</p><pre><code>systemctl enable jenkins
</code></pre><p>Jenkins默认使用端口8080。可以通过访问 <a href="http://localhost:8080" target="_blank" rel="noreferrer">http://localhost:8080</a> 来访问Jenkins。</p><p>Jenkins的配置文件存放在 <code>/etc/sysconfig/jenkins</code>，如果需要修改配置，可通过修改此文件完成。</p><p>首次启动后，需要使用初始密钥，并且建议安装建议的插件。</p><h2 id="在-jenkins-中配置-jdk-maven-和-docker" tabindex="-1">在 Jenkins 中配置 JDK，Maven 和 Docker <a class="header-anchor" href="#在-jenkins-中配置-jdk-maven-和-docker" aria-label="Permalink to &quot;在 Jenkins 中配置 JDK，Maven 和 Docker&quot;">​</a></h2><ul><li>对于Java应用来说，需要使用 JDK 包。同时还需要Maven 工具进行构建，于是需要在 Jenkins 中配置 JDK，Maven。</li><li>对于应用的发布，部署等，使用 Docker 容器化是一个好的方案，因此需要在 Jenkins 中配置 Docker。</li></ul><p>三者都是在 Manage Jenkins -&gt; Global Tool Configuration 中进行配置。</p><blockquote><p>配置 Docker 需要提前装好 Docker Commons Plugin 插件，不过只要在安装Jenkins时安装了建议的插件，就无需手动安装</p></blockquote><h3 id="jdk" tabindex="-1">JDK <a class="header-anchor" href="#jdk" aria-label="Permalink to &quot;JDK&quot;">​</a></h3><ul><li>在 Global Tool Configuration 中找到 JDK，点击 JDK Installations</li><li>点击 ADD JDK，Name中填写 <code>jdk-8u221</code></li><li>勾选 <code>Install automatically</code></li><li>点击 Add Installer，选择<code>Install from Java SE Development Kit from the website</code>，版本选择 8u221</li><li>根据提示输入 Oracle 账号密码。</li><li>点击 Apply 应用此配置。</li></ul><h3 id="maven" tabindex="-1">Maven <a class="header-anchor" href="#maven" aria-label="Permalink to &quot;Maven&quot;">​</a></h3><ul><li>在 Global Tool Configuration 中找到 Maven，点击 Maven Installations</li><li>点击 Add Maven，Name 填写 <code>mvn-3.6.2</code></li><li>勾选 <code>Install automatically</code></li><li>点击 Add Installer，选择 Install from Apache，选择版本<code>3.6.2</code></li><li>点击 Apply 应用此配置</li></ul><h3 id="docker" tabindex="-1">Docker <a class="header-anchor" href="#docker" aria-label="Permalink to &quot;Docker&quot;">​</a></h3><ul><li>在 Global Tool Configuration 中找到 Docker，点击 Docker Installations</li><li>点击 Add Docker，Name中填写 <code>myDocker</code></li><li>勾选 <code>Install automatically</code></li><li>点击 Add Installer，版本选择 latest</li><li>点击 Apply 应用此配置。</li></ul><blockquote><p>注意此方法是在 Jenkins 环境中安装 Docker Client，其默认还是与宿主机上的<code>/var/run/docker.sock</code>进行通信，因此需要保证Jenkins的宿主机上有可用的 Docker Engine</p></blockquote><h2 id="在-jenkins-中使用-docker-plugin-一般无需使用" tabindex="-1">在 Jenkins 中使用 Docker Plugin （一般无需使用） <a class="header-anchor" href="#在-jenkins-中使用-docker-plugin-一般无需使用" aria-label="Permalink to &quot;在 Jenkins 中使用 Docker Plugin （一般无需使用）&quot;">​</a></h2><p>这是除了以上方法外，另一种在 Jenkins 中使用Docker的方法，主要由Docker Plugin插件实现。由于配置比较麻烦，一般无需使用。</p><ol><li>进入 Manage Jenkins -&gt; Manage Plugins -&gt; Avaliable.</li><li>搜索 Docker，选择<code>Docker plugin</code>插件，勾选后点击 <code>Install without Restart</code>，等待插件安装完毕。</li></ol><p>安装好插件后，需要进行相关配置。</p><ol><li>进入 <code>Manage Jenkins -&gt; Configure System</code>。</li><li>拉到最底部，点击 <code>Add a new cloud -&gt; Docker</code>.</li><li>点击 <code>Docker Cloud Detail</code>，在 Docker Host URL 中填写 <code>unix:///var/run/docker.sock</code></li><li>点击 Test Connection 测试是否能够连接本机上的 Docker Engine。</li></ol><blockquote><p>如果在 Test Connection 时出现权限不够的问题，可以在终端中执行 <code>chmod 777 /var/run/docker.sock</code>来修改文件的访问权限。</p></blockquote><ol start="5"><li>勾选 <code>Enabled</code></li></ol><p>然后对 Docker Agent Template进行配置。</p><ol start="6"><li>点击 <code>Docker Agent Templates</code>，点击 <code>Add Docker Template</code>。</li><li>在 Labels 中填入 <code>docker-agent</code></li><li>勾选 <code>Enabled</code></li><li>在 Name 中填入 <code>docker</code>.</li><li>在 Docker Image 中填入 <code>benhall/dind-jenkins-agent:v2</code>。（该镜像来自<a href="https://hub.docker.com/r/benhall/dind-jenkins-agent/" target="_blank" rel="noreferrer">这里</a>)</li><li>点击 Container Settings，在volumes中填写 <code>/var/run/docker.sock:/var/run/docker.sock</code>. 该选项使我们创建的容器能够访问宿主机的 docker.sock</li><li>在 Connect Method 中选择 <code>Connect with SSH</code>.因为这个镜像是基于 <code>Jenkins SSH Slave</code> image建立的，所以默认的SSH Key就能够处理认证问题。</li><li>确认勾选了Enabled，点击保存。</li></ol><p>至此 Docker配置完成，可以在 Pipeline中使用 Docker相关命令了。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://wiki.jenkins.io/display/JENKINS/Installing+Jenkins+on+Red+Hat+distributions" target="_blank" rel="noreferrer">Installing Jenkins on RedHat distributions</a></p><p><a href="https://www.katacoda.com/courses/jenkins/build-docker-images#" target="_blank" rel="noreferrer">Build docker image in Jenkins</a></p>`,40)])])}const h=n(i,[["render",t]]);export{u as __pageData,h as default};
